changeSet.sql:
ALTER TABLE estate_fees ENABLE ROW LEVEL SECURITY;
ALTER TABLE estate_fees FORCE ROW LEVEL SECURITY;
ALTER TABLE estate_refund_terms ENABLE ROW LEVEL SECURITY;
ALTER TABLE estate_refund_terms FORCE ROW LEVEL SECURITY;
ALTER TABLE estate_default_terms ENABLE ROW LEVEL SECURITY;
